package com.fabio.ricorda;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class LanguageCatalogTest {
 @Test public void stableStorageMappingsAndNativeNamesArePreserved(){assertArrayEquals(new String[]{"it","en","es","pt-BR","fr","de","zh-Hans","ja","ko","ru"},Arrays.copyOf(LanguageCatalog.TAGS,10));assertArrayEquals(new String[]{"Italiano","English","Español","Português (Brasil)","Français","Deutsch","简体中文","日本語","한국어","Русский"},Arrays.copyOf(LanguageCatalog.NAMES,10));}
 @Test public void alphabeticalMenuRetainsEveryLanguageExactlyOnce(){Set<String> tags=new HashSet<>();for(int index:LanguageCatalog.alphabeticalOrder()){assertTrue(index>=0&&index<40);assertTrue(tags.add(LanguageCatalog.TAGS[index]));}assertEquals(new HashSet<>(Arrays.asList(LanguageCatalog.TAGS)),tags);}
 @Test public void latinNativeNamesAreAlphabeticalIncludingAccents(){List<String> names=new ArrayList<>();for(int index:LanguageCatalog.alphabeticalOrder())if(Character.UnicodeScript.of(LanguageCatalog.NAMES[index].codePointAt(0))==Character.UnicodeScript.LATIN)names.add(LanguageCatalog.NAMES[index]);assertEquals(Arrays.asList("Bahasa Indonesia","Bahasa Melayu","Čeština","Dansk","Deutsch","English","Español","Filipino","Français","Italiano","Kiswahili","Magyar","Nederlands","Norsk bokmål","Polski","Português (Brasil)","Română","Slovenčina","Suomi","Svenska","Tiếng Việt","Türkçe"),names);}
 @Test public void displaySortingDoesNotAlterSavedPreferenceMappings(){String[] tags=LanguageCatalog.TAGS.clone(),names=LanguageCatalog.NAMES.clone();int[] order=LanguageCatalog.alphabeticalOrder();for(int index:order)assertEquals(tags[index],LanguageCatalog.resolve(LanguageCatalog.TAGS[index]));order[0]=-1;assertTrue(LanguageCatalog.alphabeticalOrder()[0]>=0);assertArrayEquals(tags,LanguageCatalog.TAGS);assertArrayEquals(names,LanguageCatalog.NAMES);}
 @Test public void everySavedLanguageSurvivesResolution(){for(String tag:LanguageCatalog.TAGS)assertEquals(tag,LanguageCatalog.resolve(tag));}
 @Test public void deviceRegionVariantsSelectAvailableTranslation(){assertEquals("it",LanguageCatalog.resolve("it-IT"));assertEquals("en",LanguageCatalog.resolve("en-US"));assertEquals("es",LanguageCatalog.resolve("es-MX"));assertEquals("pt-BR",LanguageCatalog.resolve("pt_PT"));assertEquals("zh-Hans",LanguageCatalog.resolve("zh-CN"));assertEquals("ru",LanguageCatalog.resolve("ru-RU"));}
 @Test public void unsupportedDeviceLanguageFallsBackToEnglish(){assertEquals("en",LanguageCatalog.resolve("is-IS"));assertEquals("en",LanguageCatalog.resolve(""));assertEquals("en",LanguageCatalog.resolve(null));}
 @Test public void firstLaunchUsesThePhoneLanguage(){assertEquals("de",LanguageCatalog.select(null,"de-DE"));assertEquals("ja",LanguageCatalog.select("system","ja-JP"));assertEquals("pt-BR",LanguageCatalog.select("system","pt-PT"));}
 @Test public void automaticModeFollowsSubsequentSystemChanges(){assertEquals("it",LanguageCatalog.select("system","it-IT"));assertEquals("es",LanguageCatalog.select("system","es-ES"));}
 @Test public void firstSupportedSystemPreferenceWins(){assertEquals("nl",LanguageCatalog.select("system","nl-NL","fr-FR","it-IT"));assertEquals("ru",LanguageCatalog.select("system","ru-RU","en-US"));assertEquals("ar",LanguageCatalog.select("system","is-IS","ar-EG"));}
 @Test public void manualLanguageOverrideRemainsUntilSystemIsChosen(){assertEquals("it",LanguageCatalog.select("it","de-DE"));assertEquals("de",LanguageCatalog.select("system","de-DE"));}
 @Test public void noSupportedSystemLanguagesUseEnglish(){assertEquals("en",LanguageCatalog.select("system","is-IS","zz"));assertEquals("en",LanguageCatalog.select(null));assertEquals("en",LanguageCatalog.select("system",(String[])null));}
 @Test public void fortyDistinctLanguagesHaveNativeNames(){assertEquals(40,LanguageCatalog.TAGS.length);assertEquals(40,LanguageCatalog.NAMES.length);assertEquals(40,new HashSet<>(Arrays.asList(LanguageCatalog.TAGS)).size());for(String name:LanguageCatalog.NAMES)assertFalse(name.trim().isEmpty());}
 @Test public void chineseScriptAndRegionAreRespected(){assertEquals("zh-Hant",LanguageCatalog.resolve("zh-TW"));assertEquals("zh-Hant",LanguageCatalog.resolve("zh-HK"));assertEquals("zh-Hant",LanguageCatalog.resolve("zh-MO"));assertEquals("zh-Hans",LanguageCatalog.resolve("zh-CN"));assertEquals("zh-Hans",LanguageCatalog.resolve("zh-SG"));assertEquals("zh-Hans",LanguageCatalog.resolve("zh-Hans-TW"));assertEquals("zh-Hant",LanguageCatalog.resolve("zh-Hant-CN"));}
 @Test public void legacyAndroidLanguageTagsAreAccepted(){assertEquals("he",LanguageCatalog.resolve("iw-IL"));assertEquals("id",LanguageCatalog.resolve("in-ID"));assertEquals("nb",LanguageCatalog.resolve("no-NO"));assertEquals("fil",LanguageCatalog.resolve("tl-PH"));}
 @Test public void rtlIsRestrictedToTheCorrectLanguages(){for(String tag:LanguageCatalog.TAGS)assertEquals(Arrays.asList("ar","he","fa","ur").contains(tag),LanguageCatalog.isRtl(tag));assertTrue(LanguageCatalog.isRtl("iw-IL"));}
 @Test public void displayLocalePreservesMatchingPhoneRegion(){assertEquals("en-GB",LanguageCatalog.displayLocale("en","en-GB").toLanguageTag());assertEquals("it",LanguageCatalog.displayLocale("it","en-US").toLanguageTag());assertEquals("zh-Hant-HK",LanguageCatalog.displayLocale("zh-Hant","zh-HK").toLanguageTag());assertEquals("zh-Hans",LanguageCatalog.displayLocale("zh-Hans","zh-TW").toLanguageTag());}
}
